./index.html:18: app.innerHTML='<header><h1>Workboard</h1></header><form id="create-form"><label for="project-name">Project name</label><input id="project-name" name="name" type="text" autocomplete="off"><button type="submit">Create project</button><p class="alert" role="alert" aria-live="polite"></p></form><div style="margin-top:20px"><label for="project-filter">Project filter</label><select id="project-filter"><option>Active</option><option>Archived</option></select></div><section class="rows" aria-label="Projects"></section>';
./index.html:20: for(const project of projects){if (Boolean(project.archived) !== (filter.value === 'Archived')) continue;const row=document.createElement('div');row.className='row';row.dataset.testid='project-row';const info=document.createElement('span');info.textContent=project.name+' ';const summary=document.createElement('span');summary.dataset.testid='project-summary';summary.textContent=`${project.completed}/${project.total} completed`;info.append(summary);row.append(info);const actions=document.createElement('span');const open=document.createElement('button');open.type='button';open.textContent='Open project';open.addEventListener('click',()=>{location.href='/projects/'+encodeURIComponent(project.id)});actions.append(open);const toggle=document.createElement('button');toggle.type='button';toggle.style.marginLeft='8px';toggle.textContent=project.archived?'Restore project':'Archive project';toggle.addEventListener('click',async()=>{try{await request('/api/projects/'+encodeURIComponent(project.id)+'/archive',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({archived:!Boolean(project.archived)})});await renderList()}catch(error){alert(error.message)}});actions.append(toggle);row.append(actions);rows.append(row)}
