./index.html:24:async function renderProject(){const id=decodeURIComponent(location.pathname.slice('/projects/'.length));try{const project=await request('/api/projects/'+encodeURIComponent(id));app.innerHTML=`<header><h1>${escapeText(project.name)}</h1><button class="back" type="button">Projects</button></header>${project.archived?'<p>Archived project</p>':''}<form id="rename-form"><label for="new-project-name">New project name</label><input id="new-project-name" name="name" type="text" autocomplete="off" ${project.archived?'disabled':''}><button type="submit" ${project.archived?'disabled':''}>Rename project</button><p class="alert" role="alert" aria-live="polite"></p></form><form id="task-form"><label for="task-title">Task title</label><input id="task-title" name="title" type="text" autocomplete="off" ${project.archived?'disabled':''}><button type="submit" ${project.archived?'disabled':''}>Create task</button><p class="alert" role="alert" aria-live="polite"></p></form><div style="margin-top:20px"><label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select></div><section class="rows" aria-label="Tasks"></section>`;app.querySelector('.back').addEventListener('click',()=>location.href='/');const renameForm=app.querySelector('#rename-form');if(renameForm)renameForm.addEventListener('submit',async event=>{event.preventDefault();const input=app.querySelector('#new-project-name'),alert=renameForm.querySelector('.alert'),name=input.value.trim();if(!name){alert.textContent='Project name is required';return}try{await request('/api/projects/'+encodeURIComponent(id)+'/rename',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});await renderProject()}catch(error){alert.textContent=error.message}});const filter=app.querySelector('#task-filter'),rows=app.querySelector('.rows');async function loadTasks(){const tasks=await request('/api/projects/'+encodeURIComponent(id)+'/tasks');rows.replaceChildren();for(const task of tasks){if(filter.value==='Open'&&task.completed||filter.value==='Completed'&&!task.completed)continue;const row=document.createElement('div');row.className='row';row.dataset.testid='task-row';const label=document.createElement('label');label.style.cssText='display:flex;align-items:center;gap:10px;margin:0';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=!!task.completed;checkbox.disabled=!!project.archived;checkbox.setAttribute('aria-label','Complete '+task.title);checkbox.style.cssText='width:auto;margin:0';checkbox.addEventListener('change',async()=>{await request('/api/projects/'+encodeURIComponent(id)+'/tasks/'+encodeURIComponent(task.id),{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed:checkbox.checked})});loadTasks()});label.append(checkbox,document.createTextNode(task.title));row.append(label);const renameInput=document.createElement('input');renameInput.type='text';renameInput.setAttribute('aria-label','New task title');renameInput.value=task.title;renameInput.disabled=!!project.archived;renameInput.style.cssText='width:190px;margin:0 8px';const renameButton=document.createElement('button');renameButton.type='button';renameButton.textContent='Rename task';renameButton.disabled=!!project.archived;renameButton.addEventListener('click',async()=>{const title=renameInput.value.trim();if(!title){alert('Task title is required');return}try{await request('/api/projects/'+encodeURIComponent(id)+'/tasks/'+encodeURIComponent(task.id)+'/rename',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({title})});await loadTasks()}catch(error){alert(error.message)}});row.append(renameInput,renameButton);rows.append(row)}}filter.addEventListener('change',loadTasks);await loadTasks();app.querySelector('#task-form').addEventListener('submit',async event=>{event.preventDefault();const input=app.querySelector('#task-title'),alert=app.querySelector('.alert'),title=input.value.trim();if(!title){alert.textContent='Task title is required';return}try{await request('/api/projects/'+encodeURIComponent(id)+'/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title})});input.value='';alert.textContent='';await loadTasks()}catch(error){alert.textContent=error.message}})}catch{location.href='/'}}
